/**
 * Opportunities page — integration slots for Reuse, Duplicates, and Unused Code.
 *
 * Routes: /p/:projectId/s/:snapshotId/opportunities/:kind
 *
 * INTEGRATION_SLOT: reuse.findings
 * INTEGRATION_SLOT: duplicates.compare
 * INTEGRATION_SLOT: unused.review
 *
 * All three kinds share the same page frame with distinct tabs.
 * To connect a feature module: see INTEGRATION_GUIDE.md
 */

import { useNavigate, useParams } from 'react-router-dom'
import { IntegrationPlaceholder } from '../../components/slots/IntegrationPlaceholder'
import type { SlotId } from '../../contexts/SlotRegistry'

type Kind = 'reuse' | 'duplicates' | 'unused'

const KIND_META: Record<Kind, { slotId: SlotId; title: string; description: string }> = {
  reuse: {
    slotId: 'reuse.findings',
    title: 'Reusable &amp; Shared Functions',
    description: 'Integration slot: put the reuse-discovery feature here. Not connected yet. The repository map and source browser work independently.',
  },
  duplicates: {
    slotId: 'duplicates.compare',
    title: 'Duplicate Code Review',
    description: 'Integration slot: put the duplicate-detection feature here. Not connected yet.',
  },
  unused: {
    slotId: 'unused.review',
    title: 'Unused Code Candidates',
    description: 'Integration slot: put the unused-code review feature here. Not connected yet.',
  },
}

const VALID_KINDS: Kind[] = ['reuse', 'duplicates', 'unused']

export default function OpportunitiesPage() {
  const { projectId = '', snapshotId = '', kind = 'reuse' } = useParams<{
    projectId: string
    snapshotId: string
    kind: string
  }>()
  const navigate = useNavigate()

  const activeKind: Kind = VALID_KINDS.includes(kind as Kind) ? (kind as Kind) : 'reuse'
  const meta = KIND_META[activeKind]

  function goTo(k: Kind) {
    navigate(`/p/${projectId}/s/${snapshotId}/opportunities/${k}`)
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div className="content-header">
        <p className="content-header__eyebrow">Opportunities</p>
        <h1 className="content-header__title">Code Opportunities</h1>
      </div>

      {/* Tabs */}
      <div style={{ borderBottom: '1px solid var(--grepo-line)', padding: '0 32px', background: 'var(--grepo-surface)', flex: 'none' }}>
        <div role="tablist" aria-label="Opportunity kind" style={{ display: 'flex', gap: 0 }}>
          {VALID_KINDS.map(k => (
            <button
              key={k}
              type="button"
              role="tab"
              aria-selected={k === activeKind}
              className={`import-tab ${k === activeKind ? 'import-tab--active' : ''}`}
              onClick={() => goTo(k)}
              style={{ textTransform: 'capitalize' }}
            >
              {k}
            </button>
          ))}
        </div>
      </div>

      <div className="content-scroll">
        {/* INTEGRATION_SLOT: reuse.findings | duplicates.compare | unused.review */}
        <IntegrationPlaceholder
          slotId={meta.slotId}
          title={meta.title}
          description={meta.description}
          onBack={() => navigate(`/p/${projectId}/s/${snapshotId}/map`)}
          backLabel="Back to Map"
          showDevDisclosure={import.meta.env.DEV}
        />
      </div>
    </div>
  )
}
